; t01_alu -- ALU operations
; Layer-3 timing program (generated by conformance/make_timing.py: edit that, not this file).
; Markers are CSR writes to RES + k; the intervals between them are what is measured. Predictions: TIMING.md
.include "conf_defs.inc"
.main
.assume MAIN_SCRATCHPAD[0..31] defined
    MOV MAIN_SCRATCHPAD[0..1] -> ALU_OPA
    MOV MAIN_SCRATCHPAD[2..3] -> ALU_OPB
    EXEC_CSR WRITE8 RES + 0, 0x40            ; marker 0
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    EXEC_CSR WRITE8 RES + 1, 0x41            ; marker 1
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    ALU ADD unsigned
    EXEC_CSR WRITE8 RES + 2, 0x42            ; marker 2
    EXEC_CSR WRITE8 RES + 3, 0x43            ; marker 3
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    EXEC_CSR WRITE8 RES + 4, 0x44            ; marker 4
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    ALU MUL unsigned
    EXEC_CSR WRITE8 RES + 5, 0x45            ; marker 5
    EXEC_CSR WRITE8 RES_DONE, 0xA5
done:
    JMP done
